inp={(2,5),(3,5),(4,3),(4,4),(4,5),(4,7),(5,3),(6,3),(6,4),(6,5),(6,6),(7,2),(7,6)}
out={(2,5),(3,2),(3,3),(4,2),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
# use dims 9x10 transformations, find translated match
transforms=[]
for name,fn in [('id',lambda r,c:(r,c)),('flipv',lambda r,c:(8-r,c)),('fliph',lambda r,c:(r,9-c)),('rot180',lambda r,c:(8-r,9-c)),('transpose',lambda r,c:(c,r)),('rot90',lambda r,c:(c,8-r)),('rot270',lambda r,c:(9-c,r)),('anti',lambda r,c:(9-c,8-r))]:
 p={fn(*x) for x in inp}
 for dr in range(-12,13):
  for dc in range(-12,13):
   if {(r+dr,c+dc) for r,c in p}==out: transforms.append((name,dr,dc))
transforms

